save('actual-targeted-official-primary-reading-a.json',{'actualReadDate':'2026-10-10','ownBoundedParaphrases':[{'officialURL':'https://www.bankofengland.co.uk/speech/2026/april/alan-taylor-at-a-joint-conference-at-the-banque-de-france','actualReadMeaning':'Official13April2026 speech section on monetary contraction, gold-standard constraints and later credit/institutional explanations actually read. Historical interpretation in a contemporary speech, no 1930s source voice or model numbers attributed to it.'},{'officialURL':'https://www.nobelprize.org/prizes/economic-sciences/1986/buchanan/lecture/','actualReadMeaning':'Actual official search-extracted opening and constitutional-policy discussion read: rules/constraints and individuals’ preferences distinguish institutional evaluation from a benevolent-policy assumption. Full direct page attempt returned403; no full-text-read claim.'},{'officialURL':'https://www.gesetze-im-internet.de/gg/art_14.html','actualReadMeaning':'Current full Art14 independently read by actual HTTPGET after web fetch failure: protected property, statutory content/limits, social obligation and separately public-purpose taking with law/compensation.'},{'officialURL':'https://www.gesetze-im-internet.de/bgb/__439.html','actualReadMeaning':'Current complete six paragraphs actually read: choice of repair/replacement, seller expense, conditional disproportionate-cost refusal, availability and return. Rule/incentive analysis does not guarantee enforcement.'}],'foreignFullTextsInRepository':False,'fullCurriculumSourceReviewRestart':False,'otherCurrentRoundRead':False,'humanClaims':False})
